                buf.replace(startPos, endPos, varValue);
                altered = true;
                int change = substitute(event, buf, startPos, varLen, priorVariables);
                change += varLen - (endPos - startPos);
                pos += change;
                bufEnd += change;
                lengthChange += change;
                chars = getChars(buf);
            }
            priorVariables.remove(priorVariables.size() - 1);
        }
        if (top) {
            return altered ? 1 : 0;
        }
        return lengthChange;
    }

    private int findVariableEnd(char[] chars, int pos, int bufEnd, StrMatcher prefixMatcher,
                                StrMatcher suffixMatcher, boolean substitutionInVariablesEnabled) {
        int nestedVarCount = 0;
        while (pos < bufEnd) {
            if (substitutionInVariablesEnabled) {
                int startMatchLen = prefixMatcher.isMatch(chars, pos, 0, bufEnd);
                if (startMatchLen != 0) {
                    nestedVarCount++;
                    pos += startMatchLen;
                    continue;
                }
            }
            int endMatchLen = suffixMatcher.isMatch(chars, pos, 0, bufEnd);
            if (endMatchLen == 0) {
                pos++;
            } else {
                if (nestedVarCount == 0) {
                    return pos + endMatchLen;
                } else {
                    nestedVarCount--;
                    pos += endMatchLen;
                }
            }
        }
        return -1;
    }

