@has_request_variables
def messages_in_narrow_backend(request: HttpRequest, user_profile: UserProfile,
                               msg_ids: List[int] = REQ(validator=check_list(check_int)),
                               narrow: Optional[List[Dict[str, Any]]] = REQ(converter=narrow_parameter)) -> HttpResponse:
    first_visible_message_id = get_first_visible_message_id(user_profile.realm)
    msg_ids = [mid for mid in msg_ids if mid >= first_visible_message_id]
    query = select(
        [column("message_id"), column("subject"), column("rendered_content")],
        and_(
            column("user_profile_id") == literal(user_profile.id),
            column("message_id").in_(msg_ids),
        ),
        join(
            table("zerver_usermessage"),
            table("zerver_message"),
            literal_column("zerver_usermessage.message_id") ==
            literal_column("zerver_message.id"),
        ),
    )
    builder = NarrowBuilder(user_profile, column("message_id"))
    if narrow:
        for term in narrow:
            query = builder.add_term(query, term)
    sa_conn = get_sqlalchemy_connection()
    query_result = list(sa_conn.execute(query).fetchall())
    search_fields: Dict[int, Dict[str, str]] = {}
    for row in query_result:
        message_id = row['message_id']
        subject = row['subject']
        rendered_content = row['rendered_content']
        if 'content_matches' in row:
            search_fields[message_id] = get_search_fields(
                rendered_content, subject,
                row['content_matches'], row['subject_matches'],
            )
        else:
            search_fields[message_id] = dict(
                match_content=rendered_content,
                match_subject=escape_html(subject),
            )
    return json_success({"messages": search_fields})

