def _validate_anchor_and_use_first_unread(anchor: Optional[int], use_first_unread_anchor: bool) -> int:
    if anchor is None and not use_first_unread_anchor:
        raise JsonableError(_("Missing 'anchor' argument (or set 'use_first_unread_anchor'=True)."))
    return anchor

def _validate_num_before_after(num_before: int, num_after: int) -> None:
    if num_before + num_after > MAX_MESSAGES_PER_FETCH:
        raise JsonableError(_("Too many messages requested (maximum %s)."
                              % (MAX_MESSAGES_PER_FETCH,)))

def _determine_query_requirements(narrow: Optional[List[Dict[str, Any]]],
                                  include_history: bool) -> Tuple[bool, bool]:
    if include_history:
        return (True, False)
    if narrow is None:
        return (False, True)
    return (True, True)

def _build_and_process_rows(rows: List[Any],
                            is_search: bool,
                            include_history: bool,
                            user_profile: UserProfile,
                            message_ids: List[int],
                            user_message_flags: Dict[int, List[str]],
                            search_fields: Dict[int, Dict[str, str]],
                            apply_markdown: bool,
                            client_gravatar: bool) -> List[Dict[str, Any]]:
    if include_history:
        message_ids = [row[0] for row in rows]
        um_rows = UserMessage.objects.filter(user_profile=user_profile,
                                             message__id__in=message_ids)
        user_message_flags.update({um.message_id: um.flags_list() for um in um_rows})
        for message_id in message_ids:
            if message_id not in user_message_flags:
                user_message_flags[message_id] = ["read", "historical"]
    else:
        for row in rows:
            message_id, flags = row[0], row[1]
            user_message_flags[message_id] = UserMessage.flags_list_for_flags(flags)
            message_ids.append(message_id)
    if is_search:
        for row in rows:
            message_id = row[0]
            subject, rendered_content, content_matches, subject_matches = row[-4:]
            try:
                search_fields[message_id] = get_search_fields(rendered_content, subject,
                                                              content_matches, subject_matches)
            except UnicodeDecodeError as err:
                raise Exception(str(err), message_id, narrow)
    return messages_for_ids(
        message_ids=message_ids,
        user_message_flags=user_message_flags,
        search_fields=search_fields,
        apply_markdown=apply_markdown,
        client_gravatar=client_gravatar,
        allow_edit_history=user_profile.realm.allow_edit_history,
    )

def _build_response(message_list: List[Dict[str, Any]],
                    query_info: Dict[str, Any],
                    anchor: int) -> Dict[str, Any]:
    return dict(
        messages=message_list,
        result='success',
        msg='',
        found_anchor=query_info['found_anchor'],
        found_oldest=query_info['found_oldest'],
        found_newest=query_info['found_newest'],
        history_limited=query_info['history_limited'],
        anchor=anchor,
    )

@has_request_variables
def get_messages_backend(request: HttpRequest, user_profile: UserProfile,
                         anchor: int=REQ(converter=int, default=None),
                         num_before: int=REQ(converter=to_non_negative_int),
                         num_after: int=REQ(converter=to_non_negative_int),
                         narrow: Optional[List[Dict[str, Any]]]=REQ('narrow', converter=narrow_parameter,
                                                                    default=None),
                         use_first_unread_anchor: bool=REQ(validator=check_bool, default=False),
                         client_gravatar: bool=REQ(validator=check_bool, default=False),
                         apply_markdown: bool=REQ(validator=check_bool, default=True)) -> HttpResponse:
    anchor = _validate_anchor_and_use_first_unread(anchor, use_first_unread_anchor)
    _validate_num_before_after(num_before, num_after)
    include_history = ok_to_include_history(narrow, user_profile)
    need_message, need_user_message = _determine_query_requirements(narrow, include_history)
    query, inner_msg_id_col = get_base_query_for_search(
        user_profile=user_profile,
        need_message=need_message,
        need_user_message=need_user_message,
    )
    query, is_search = add_narrow_conditions(
        user_profile=user_profile,
        inner_msg_id_col=inner_msg_id_col,
        query=query,
        narrow=narrow,
    )
    if narrow is not None:
        verbose_operators = []
        for term in narrow:
            if term['operator'] == "is":
                verbose_operators.append("is:" + term['operand'])
            else:
                verbose_operators.append(term['operator'])
        request._log_data['extra'] = "[%s]" % (",".join(verbose_operators),)
    sa_conn = get_sqlalchemy_connection()
    if use_first_unread_anchor:
        anchor = find_first_unread_anchor(sa_conn, user_profile, narrow)
    anchored_to_left = (anchor == 0)
    anchored_to_right = (anchor == LARGER_THAN_MAX_MESSAGE_ID)
    if anchored_to_right:
        num_after = None
    first_visible_message_id = get_first_visible_message_id(user_profile.realm)
    query = limit_query_to_range(
        query=query,
        num_before=num_before,
        num_after=num_after,
        anchor=anchor,
        anchored_to_left=anchored_to_left,
        anchored_to_right=anchored_to_right,
        id_col=inner_msg_id_col,
        first_visible_message_id=first_visible_message_id,
    )
    main_query = alias(query)
    query = select(main_query.c, None, main_query).order_by(column("message_id").asc())
    query = query.prefix_with("/* get_messages */")
    rows = list(sa_conn.execute(query).fetchall())
    query_info = post_process_limited_query(
        rows=rows,
        num_before=num_before,
        num_after=num_after,
        anchor=anchor,
        anchored_to_left=anchored_to_left,
        anchored_to_right=anchored_to_right,
        first_visible_message_id=first_visible_message_id,
    )
    message_ids: List[int] = []
    user_message_flags: Dict[int, List[str]] = {}
    search_fields: Dict[int, Dict[str, str]] = {}
    message_list = _build_and_process_rows(
        rows, is_search, include_history, user_profile,
        message_ids, user_message_flags, search_fields,
        apply_markdown, client_gravatar)
    statsd.incr('loaded_old_messages', len(message_list))
    return json_success(_build_response(message_list, query_info, anchor))

def limit_query_to_range(query: Query,
                         num_before: int,
                         num_after: int,
                         anchor: int,
                         anchored_to_left: bool,
                         anchored_to_right: bool,
                         id_col: ColumnElement,
                         first_visible_message_id: int) -> Query:
    need_before_query = (not anchored_to_left) and (num_before > 0)
    need_after_query = (not anchored_to_right) and (num_after > 0)
    need_both_sides = need_before_query and need_after_query
    if need_both_sides:
        before_anchor = anchor - 1
        after_anchor = max(anchor, first_visible_message_id)
        before_limit = num_before
        after_limit = num_after + 1
    elif need_before_query:
        before_anchor = anchor
        before_limit = num_before
        if not anchored_to_right:
            before_limit += 1
    elif need_after_query:
        after_anchor = max(anchor, first_visible_message_id)
        after_limit = num_after + 1
    if need_before_query:
        before_query = query
        if not anchored_to_right:
            before_query = before_query.where(id_col <= before_anchor)
        before_query = before_query.order_by(id_col.desc()).limit(before_limit)
    if need_after_query:
        after_query = query
        if not anchored_to_left:
            after_query = after_query.where(id_col >= after_anchor)
        after_query = after_query.order_by(id_col.asc()).limit(after_limit)
    if need_both_sides:
        query = union_all(before_query.self_group(), after_query.self_group())
    elif need_before_query:
        query = before_query
    elif need_after_query:
        query = after_query
    else:
        query = query.where(id_col == anchor)
    return query

def post_process_limited_query(rows: List[Any],
                               num_before: int,
                               num_after: int,
                               anchor: int,
                               anchored_to_left: bool,
                               anchored_to_right: bool,
                               first_visible_message_id: int) -> Dict[str, Any]:
    visible_rows = [r for r in rows if r[0] >= first_visible_message_id] if first_visible_message_id > 0 else rows
    rows_limited = len(visible_rows) != len(rows)
    if anchored_to_right:
        num_after = 0
        before_rows = visible_rows[:]
        anchor_rows = []
        after_rows = []
    else:
        before_rows = [r for r in visible_rows if r[0] < anchor]
        anchor_rows = [r for r in visible_rows if r[0] == anchor]
        after_rows = [r for r in visible_rows if r[0] > anchor]
    if num_before:
        before_rows = before_rows[-1 * num_before:]
    if num_after:
        after_rows = after_rows[:num_after]
    visible_rows = before_rows + anchor_rows + after_rows
    found_anchor = len(anchor_rows) == 1
    found_oldest = anchored_to_left or (len(before_rows) < num_before)
    found_newest = anchored_to_right or (len(after_rows) < num_after)
    history_limited = rows_limited and found_oldest
    return dict(
        rows=visible_rows,
        found_anchor=found_anchor,
        found_newest=found_newest,
        found_oldest=found_oldest,
        history_limited=history_limited,
    )

